#include "v32bis_map.h"
#include <assert.h>
#include <stdio.h>
static void check_rate(int rate,unsigned count){for(unsigned label=0;label<count;label++){struct v32bis_point p;assert(v32bis_map_point(rate,label,&p)==0);for(unsigned other=0;other<label;other++){struct v32bis_point q;assert(v32bis_map_point(rate,other,&q)==0);assert(p.i!=q.i||p.q!=q.q);}unsigned got=999;double d=-1;assert(v32bis_map_nearest(rate,p.i+.1,p.q-.1,&got,&d)==0&&got==label&&d<.021);}struct v32bis_point p;assert(v32bis_map_point(rate,count,&p)<0);}
int main(void){check_rate(7200,16);check_rate(9600,32);check_rate(12000,64);check_rate(14400,128);struct v32bis_point p;assert(v32bis_map_point(7200,0,&p)==0&&p.i==3&&p.q==-3);assert(v32bis_map_point(9600,0,&p)==0&&p.i==-4&&p.q==1);assert(v32bis_map_point(12000,0,&p)==0&&p.i==7&&p.q==1);assert(v32bis_map_point(14400,0,&p)==0&&p.i==-8&&p.q==-1);assert(v32bis_map_point(4800,0,&p)<0);puts("V.32bis constellations: 16/32/64/128 mappings and nearest decisions pass");return 0;}
